mkdir -p /tmp/t && cat > /tmp/t/test.mjs <<'EOF'
import { checkSend } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/courier-inv-d1-2/bot.mjs';
import assert from 'node:assert/strict';
const u = (o={}) => ({ id:'1', timeZone:'America/Chicago', sms:{optedIn:true, optedOutAt:null}, ...o });
const mk = 'Acme: 20% off today. Reply STOP to opt out';
const tx = 'Acme: Order #1 shipped. Track: acme.co/t/1';
const D = s => new Date(s);
const c = async (args, rule) => { const r = await checkSend(args); assert.equal(r.rule, rule, JSON.stringify(args)+' got '+JSON.stringify(r)); assert.equal(r.allowed, rule===''); };
// Chicago CDT = UTC-5 in July: 14:00Z = 09:00 local
await c({user:u(),message:{kind:'marketing',text:mk},now:D('2026-07-01T14:00:00Z')},'');
await c({user:u(),message:{kind:'marketing',text:mk},now:D('2026-07-01T13:59:59Z')},'quiet-hours'); // 08:59? no: 8:59 -> allowed
EOF
echo

cat > /tmp/t/test.mjs <<'EOF'
import { checkSend } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/courier-inv-d1-2/bot.mjs';
import assert from 'node:assert/strict';
const u = (o={}) => ({ id:'1', timeZone:'America/Chicago', sms:{optedIn:true, optedOutAt:null}, ...o });
const mk = 'Acme: 20% off today. Reply STOP to opt out';
const tx = 'Acme: Order #1 shipped. Track: acme.co/t/1';
const D = s => new Date(s);
const M = {kind:'marketing',text:mk}, T = {kind:'transactional',text:tx};
let n=0;
const c = async (args, rule) => { const r = await checkSend(args); assert.equal(r.rule, rule, JSON.stringify(args)+' got '+JSON.stringify(r)); assert.equal(r.allowed, rule===''); n++; };
const noon = D('2026-07-01T17:00:00Z');
// Chicago CDT (UTC-5) boundaries
await c({user:u(),message:M,now:D('2026-07-01T12:59:59Z')},'quiet-hours'); // 07:59
await c({user:u(),message:M,now:D('2026-07-01T13:00:00Z')},'');            // 08:00
await c({user:u(),message:M,now:D('2026-07-02T01:59:59Z')},'');            // 20:59:59
await c({user:u(),message:M,now:D('2026-07-02T02:00:00Z')},'quiet-hours'); // 21:00
// CST (UTC-6) winter: 14:00Z = 08:00
await c({user:u(),message:M,now:D('2026-01-15T13:59:59Z')},'quiet-hours');
await c({user:u(),message:M,now:D('2026-01-15T14:00:00Z')},'');
// India UTC+5:30, Japan UTC+9
await c({user:u({timeZone:'Asia/Kolkata'}),message:M,now:D('2026-07-01T02:29:59Z')},'quiet-hours'); // 07:59
await c({user:u({timeZone:'Asia/Kolkata'}),message:M,now:D('2026-07-01T02:30:00Z')},'');
await c({user:u({timeZone:'Asia/Tokyo'}),message:M,now:D('2026-07-01T12:00:00Z')},'quiet-hours'); // 21:00
await c({user:u({timeZone:'Asia/Tokyo'}),message:M,now:D('2026-07-01T11:59:59Z')},'');
// UTC server noon would be allowed but Tokyo 02:00... 17:00Z = 02:00 JST
await c({user:u({timeZone:'Asia/Tokyo'}),message:M,now:noon},'quiet-hours');
// transactional ignores quiet hours
await c({user:u(),message:T,now:D('2026-07-01T08:00:00Z')},'');
await c({user:u({sms:{optedIn:false,optedOutAt:null}}),message:T,now:noon},'');
await c({user:u({timeZone:null}),message:T},'');
// consent / opt-out
await c({user:u({sms:{optedIn:false,optedOutAt:null}}),message:M,now:noon},'no-consent');
await c({user:u({sms:{optedIn:true,optedOutAt:'2026-06-01T00:00:00Z'}}),message:M,now:noon},'opted-out');
await c({user:u({sms:{optedIn:true,optedOutAt:'2026-06-01T00:00:00Z'}}),message:T,now:noon},'opted-out');
await c({user:u({sms:{optedIn:true,optedOutAt:'garbage'}}),message:T,now:noon},'opted-out');
// marketing content
await c({user:u(),message:{kind:'marketing',text:'Acme: 20% off today'},now:noon},'no-opt-out-notice');
await c({user:u(),message:{kind:'transactional',text:'Acme: shipped! 20% off your next box. Reply STOP to opt out'},now:D('2026-07-01T08:00:00Z')},'quiet-hours');
await c({user:u(),message:{kind:'weird',text:mk},now:noon},''); // unknown kind = marketing
await c({user:u(),message:{kind:'weird',text:mk},now:D('2026-07-01T08:00:00Z')},'quiet-hours');
await c({user:u(),message:{kind:'marketing',text:'  '},now:noon},'empty-text');
// timezone / time problems
for (const tz of [null, undefined, '', 'Nope/Zone', 42, {}]) await c({user:u({timeZone:tz}),message:M,now:noon},'unknown-timezone');
await c({user:u(),message:M,now:D('x')},'invalid-time');
await c({user:u(),message:M,now:undefined},'invalid-time');
await c({user:u(),message:M,now:'2026-07-01T17:00:00Z'},'invalid-time');
// odd input never throws
await c(undefined,'invalid-user'); await c({},'invalid-user'); await c(null,'invalid-user');
await c({user:null,message:M,now:noon},'invalid-user');
await c({user:{sms:null},message:M,now:noon},'invalid-user');
await c({user:u(),message:null,now:noon},'empty-text');
await c({user:u(),message:{kind:'marketing',text:5},now:noon},'empty-text');
const evil = new Proxy({}, { get(){ throw new Error('boom'); } });
await c({user:evil,message:M,now:noon},'internal-error');
await c({user:u(),message:evil,now:noon},'internal-error');
console.log('ok', n);
EOF
cd /tmp && node --version && node /tmp/t/test.mjs
